chuck/0.ck:
// 0.ck - clean two-saw "fifth" drone for the chuck engine (ENGINE=chuck). A calm baseline patch,
// entirely knob-controlled. Same global vocabulary as the built-in program, so the same knobs drive it.
//   PITCH (speedA) = pitch, SIZE (sizeA) = brightness, MIX (mixA) = level.

global float speedA;
global float mixA;
global float sizeA;

SawOsc root => LPF f => dac;
SawOsc fifth => f;                 // a second saw, a perfect fifth above, into the same low-pass
0.7 => f.Q;

while( true )
{
    110.0 + speedA * 440.0 => float hz;     // PITCH -> root pitch (110..550 Hz)
    hz       => root.freq;
    hz * 1.5 => fifth.freq;                 // perfect fifth
    1500.0 + sizeA * 6000.0 => f.freq;      // SIZE -> brightness (undriven => 1500 Hz)
    (0.12 + mixA * 0.8) * 0.25 => float g;  // MIX -> level, with a floor so boot is audible
    g => root.gain;
    g => fifth.gain;
    10::ms => now;                          // block-rate control update (cheap)
}

chuck/1.ck:
// 1.ck - fat detuned super-saw with a sub-octave. Thicker and bassier than 0.ck, so the difference is
// obvious when you Alt+PITCH between the two slots (a good live-switch test). Knob-controlled.
//   PITCH (speedA) = pitch, SIZE (sizeA) = brightness, MIX (mixA) = level.

global float speedA;
global float mixA;
global float sizeA;

SawOsc a => LPF f => dac;
SawOsc b => f;
SawOsc c => f;
SawOsc sub => f;
0.7 => f.Q;

while( true )
{
    40.0 + speedA * 300.0 => float hz;      // lower range -> bassier than 0.ck
    hz         => a.freq;
    hz * 1.006 => b.freq;                   // detune up   -> slow beating
    hz * 0.994 => c.freq;                   // detune down -> fatter
    hz * 0.5   => sub.freq;                 // sub-oscillator an octave below
    180.0 + sizeA * 5000.0 => f.freq;       // SIZE -> brightness
    (0.1 + mixA * 0.8) * 0.18 => float g;   // MIX -> level (lower base gain: four oscillators sum)
    g       => a.gain;
    g       => b.gain;
    g       => c.gain;
    g * 1.2 => sub.gain;
    10::ms => now;
}

chuck/2.ck:
// 2.ck - concurrent generative pad. Several voice shreds run at once, each on its own clock, so the
// patch plays itself in polyrhythm. This is the patch that shows off ChucK's strength (and exercises
// the METER build's ring B = live shred count: you should see several cyan dots, not one). No MIDI.
//   PITCH (speedA) = tempo, SIZE (sizeA) = brightness, MIX (mixA) = level.

global float speedA;
global float mixA;
global float sizeA;

// Shared output: a summing bus into one low-pass that all voices share.
Gain bus => LPF f => dac;
0.5 => bus.gain;
1.0 => f.Q;

[0, 3, 5, 7, 10] @=> int scale[];   // minor-pentatonic semitone offsets
36 => int root;                     // base note

// Brightness follower - its own shred, so SIZE tracks live while the voices play.
fun void controls()
{
    while( true )
    {
        400.0 + sizeA * 6000.0 => f.freq;
        10::ms => now;
    }
}

// One voice: pluck random scale notes on its own clock. `oct` transposes it; `mult` skews its tempo,
// so the voices drift against each other (polyrhythm). Loops forever -> stays a live shred.
fun void voice( int oct, float mult )
{
    SawOsc s => ADSR e => bus;
    e.set( 4::ms, 140::ms, 0.0, 60::ms );
    while( true )
    {
        // PITCH -> tempo: higher speedA shortens the period (~360 ms down to ~60 ms), skewed per voice.
        (60.0 + (1.0 - speedA) * 300.0) * mult => float period;
        period * 0.8 => float on;
        period * 0.2 => float off;
        scale[Math.random2(0, scale.size() - 1)] + root + oct * 12 => int note;
        Std.mtof( note ) => s.freq;
        (0.04 + mixA * 0.22) => s.gain;
        e.keyOn();
        on::ms => now;
        e.keyOff();
        off::ms => now;
    }
}

spork ~ controls();
spork ~ voice( 1, 1.0 );
spork ~ voice( 2, 0.75 );
spork ~ voice( 3, 1.5 );

// Keep the main shred alive so the program (and its sporked children) keeps running.
while( true ) 1::second => now;

chuck/3.ck:
// 3.ck - STK Rhodey (electric piano) auto-arpeggio. Shows that the STK instruments link into this
// build (not just the raw oscillators). Self-running, no MIDI needed.
//   PITCH (speedA) = tempo, SIZE (sizeA) = brightness, MIX (mixA) = level.

global float speedA;
global float mixA;
global float sizeA;

Rhodey ep => LPF f => dac;
2.0 => f.Q;

[0, 4, 7, 11, 12, 7] @=> int arp[];   // a major-7 arpeggio, up then partway down
48 => int root;
0 => int i;

while( true )
{
    400.0 + sizeA * 6000.0 => f.freq;            // SIZE -> brightness
    (0.2 + mixA * 0.7) => ep.gain;               // MIX -> level
    arp[i % arp.size()] + root => int note;
    Std.mtof( note ) => ep.freq;
    0.8 => ep.noteOn;                            // strike the note
    60.0 + (1.0 - speedA) * 340.0 => float period;   // PITCH -> tempo (~400 ms down to ~60 ms)
    period::ms => now;
    i++;
}

chuck/4.ck:
// 4.ck - "a chuck is born" (the classic random-melody example), now driven by the panel knobs.
//   PITCH (speedA) = tempo, SIZE (sizeA) = reverb amount (space), MIX (mixA) = level.

global float speedA;   // PITCH -> tempo
global float sizeA;    // SIZE  -> reverb mix
global float mixA;     // MIX   -> level

SinOsc s => JCRev r => dac;

// a scale (semitone offsets) to pick notes from
[ 0, 2, 4, 7, 9, 11 ] @=> int hi[];

while( true )
{
    // controls, read live each step
    (0.05 + mixA * 0.45)  => s.gain;     // MIX  -> level
    (0.02 + sizeA * 0.60) => r.mix;      // SIZE -> reverb amount (dry..wet)

    // random note from the scale, across a few octaves
    Std.mtof( 45 + Math.random2(0,3) * 12 + hi[Math.random2(0,hi.size()-1)] ) => s.freq;

    // PITCH -> tempo: ~40 ms (fast) up to ~280 ms (slow)
    40.0 + (1.0 - speedA) * 240.0 => float period;
    period::ms => now;
}

chuck/5.ck:
//---------------|
// karp-o-matic!
// by: Ge Wang (gewang@cs.princeton.edu)
//     Perry R. Cook (prc@cs.princeton.edu)
//------------------|
// Full network-reverb version (StifKarp -> JCRev -> three Echos), with panel controls added.
// PITCH (speedA) = octave shift, SIZE (sizeA) = echo amount, MIX (mixA) = level.

global float speedA;   // PITCH -> octave shift
global float sizeA;    // SIZE  -> echo amount (echo mix depth)
global float mixA;     // MIX   -> level

// our patch (master Gain g carries the MIX -> level control)
StifKarp karp => JCRev r => Echo a => Echo b => Echo c => Gain g => dac;
// set the gain
.95 => r.gain;
// set the reverb mix
.02 => r.mix;
// set max delay for echo
1000::ms => a.max => b.max => c.max;
// set delay for echo
750::ms => a.delay => b.delay => c.delay;
// set the initial effect mix
0.0 => a.mix => b.mix => c.mix;

// scale
[ 0, 2, 4, 7, 9 ] @=> int scale[];

// our main loop
while( true )
{
    // MIX -> level
    (0.2 + mixA * 0.6) => g.gain;
    // SIZE -> echo amount: set echo mix depth directly
    (0.05 + sizeA * 0.5) => a.mix;
    (0.05 + sizeA * 0.4) => b.mix;
    (0.05 + sizeA * 0.3) => c.mix;
    // position
    Math.random2f( 0.2, 0.8 ) => karp.pickupPosition;
    // frequency...
    scale[Math.random2(0,scale.size()-1)] => int freq;
    // PITCH -> octave: base 220 Hz shifted up to +3 octaves; plus a random octave + the scale degree
    220.0 * Math.pow( 2.0, speedA*2.0 )
          * Math.pow( 1.05946, (Math.random2(0,2)*12)
                      +freq ) => karp.freq;
    // pluck it!
    0.0 => karp.stretch;
    Math.random2f( 0.2, 0.9 ) => karp.pluck;

    // note: Math.randomf() return value between 0 and 1
    if( Math.randomf() > 0.9 )
    { 500::ms => now; }
    else if( Math.randomf() > .925 )
    { 250::ms => now; }
    else if( Math.randomf() > .05 )
    { .125::second => now; }
    else
    {
        1 => int i => int pick_dir;
        // how many times
        4 * Math.random2( 1, 5 ) => int pick;
        0.0 => float pluck;
        0.7 / pick => float inc;
        // time loop
        for( ; i < pick; i++ )
        {
            75::ms => now;
            Math.random2f(.2,.3) + i*inc => pluck;
            i * 0.025 => karp.stretch;
            pluck + -.2 * pick_dir => karp.pluck;
            // simulate pluck direction
            !pick_dir => pick_dir;
        }
        // let time pass for final pluck
        75::ms => now;
    }
}

chuck/6.ck:
// 6.ck - karp-o-matic (Ge Wang / Perry R. Cook), lightened for the Daisy. The stock patch runs a
// StifKarp through JCRev + three Echos; the network reverb (JCRev) is the budget killer on this MCU, so
// it's dropped here - a StifKarp through two cheap Echo delay lines (delay lines are inexpensive per
// sample; the network reverbs NRev/JCRev are not). Add controls for the panel.
//   PITCH (speedA) = octave, SIZE (sizeA) = echo amount, MIX (mixA) = level.

global float speedA;   // PITCH -> octave shift
global float sizeA;    // SIZE  -> echo mix
global float mixA;     // MIX   -> level

// one plucked-string voice through two echo delay lines (no JCRev)
StifKarp karp => Gain g => Echo a => Echo b => dac;
g => dac;                                  // dry path alongside the echoes
500::ms => a.max => b.max;
375::ms => a.delay => b.delay;

// scale (semitone offsets)
[ 0, 2, 4, 7, 9 ] @=> int scale[];

while( true )
{
    (0.2 + mixA * 0.6) => g.gain;          // MIX -> level
    (0.05 + sizeA * 0.5) => a.mix;         // SIZE -> echo amount
    (0.05 + sizeA * 0.4) => b.mix;

    Math.random2f( 0.2, 0.8 ) => karp.pickupPosition;
    scale[Math.random2(0,scale.size()-1)] => int deg;
    // PITCH -> octave: base 110 Hz, up to +3 octaves; plus a random octave + the scale degree
    110.0 * Math.pow( 2.0, speedA*2.0 )
          * Math.pow( 1.05946, (Math.random2(0,2)*12) + deg ) => karp.freq;
    0.0 => karp.stretch;
    Math.random2f( 0.2, 0.9 ) => karp.pluck;

    if( Math.randomf() > 0.9 )       500::ms => now;
    else if( Math.randomf() > .925 ) 250::ms => now;
    else                             .125::second => now;
}

chuck/7.ck:
//------------------------------------------------------------------
// name: oscillatronx (oscillator demo)
// desc: playing all of the different types of oscillator UGens
//       mixing together different timbres to create a sonic texture
//
// author: philipd
//------------------------------------------------------------------

// panel controls (A-deck globals read live in the loop)
global float speedA;   // PITCH    -> base note (transpose)
global float mixA;     // MIX      -> master level
global float sizeA;    // SIZE     -> FM index (timbre: clean .. clangorous)
global float modspA;   // ModSpeed -> event / wiggle rate (density)
global float modampA;  // ModAmp   -> pulse-width sweep depth

// scale degrees in semi-tones
[ 0, 2, 4, 7, 9 ] @=> int f[];

// master bus so MIX has a level to ride
Gain master => dac;

// various oscialltors
SinOsc s => master;
SawOsc saw => master;
TriOsc tri => master;
PulseOsc pul => master;
SqrOsc sqr => master;
// FM modulator and carrier
TriOsc trictrl => SinOsc sintri => master;
// interpret input as frequency modulation
2 => sintri.sync;
100  => trictrl.gain;

// array of Oscs
[ s, saw, tri, pul, sqr, trictrl ] @=> Osc oscillators[];

// set gains
0.2 => s.gain;
0.1 => saw.gain;
0.1 => tri.gain;
0.1 => pul.gain;
0.1 => sqr.gain;
0.1 => sintri.gain;

// infinite time-loop
while( true )
{
    // MIX -> master level (keep an audible floor)
    (0.3 + mixA * 0.7) => master.gain;
    // SIZE -> FM index: clean sine .. clangorous FM
    (20.0 + sizeA * 380.0) => trictrl.gain;
    // PITCH -> base note: ~2 octaves of transpose around MIDI 48
    48 + (speedA * 24.0) $ int => int base;
    // ModSpeed -> event/wiggle rate (higher = denser/faster)
    (0.40 - modspA * 0.32) => float step;
    (0.08 - modspA * 0.065) => float wig;
    // ModAmp -> pulse-width sweep depth around 0.5
    0.1 + modampA * 0.4 => float wd;

    // randomize
    Math.random2(0,7) => int select;
    // clamp (giving more weight to 5)
    if( select > 5 ) 5 => select;
    // generate new frequenc value
    Std.mtof( f[Math.random2( 0, 4 )] + base ) => float newnote;
    // set frequency
    newnote => oscillators[select].freq;
    // wait a bit
    step::second => now;
    // 10 times
    repeat(10)
    {
        Math.random2f( 0.5 - wd, 0.5 + wd ) => trictrl.width;
        // <<< "trictrl width:", trictrl.width() >>>;
        wig::second => now;
    }
}
